<!DOCTYPE html>
<html lang="{{ str_replace('_', '-', app()->getLocale()) }}">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=0,viewport-fit=cover">
        <title>{{ config('app.name') }}</title>
        <link rel="stylesheet" href="{{ config('api.basics.cdn') }}/theme/weui/css/weui.min.css">
        <link rel="stylesheet" href="{{ config('api.basics.cdn') }}/theme/weui/css/bootstrap.min.css">
    </head>
    <body>
        <div id="dialog"></div>
        <header class="header"></header>
        <div class="weui-tab"></div>
        <footer class="footer"></footer>
    </body>
    <script>
        /**
         * V2-2.0.0起 为适配代理 HTML 功能 已去除大部分后台控制功能【包含：购买地址、功能修改、等等】
         * 只保留了：前端重签名修改安装包总开关【如果后台关闭、前端开启也一样无法修改 反之则能自定义隐藏显示对应功能】
         **/
        window.customConfig = {
            siteAPI: '{{ config('app.url') }}',         // 对接接口【此处一般无需修改、按默认值即可】
            siteToken: '',                              // 分站令牌【主站留空、分站配置此项完成对接】
            /**
             * 获取 UDID 描述文件说明
             * 请自行下载保存：open.mobileprovision 到您的网站下载（自动跳转手机设置描述文件）
             * 请自行下载保存修改：/api/udid.mobileconfig 到您的网站下载（获取设备码描述文件）
             **/

            /**
             * 链接相关
             **/
            buyURL: '{{ config('app.url') }}',          // 购买卡密跳转地址
            /**
             * 显示开关
             **/
            displayHelpList: true,                      // 是否显示帮助列表 【false=隐藏、true=显示】
            displayAboutUSItem: true,                   // 是否显示关于我们 【false=隐藏、true=显示】关于我们中的官方自定义URL
            displayCertDownload: true,                  // 是否显示证书下载【false=隐藏、true=显示】
            displayCertDetection: true,                 // 是否显示证书检测【false=隐藏、true=显示】
            /**
             * 基础配置
             **/
            debug: true,                                // 调试模式【false=关闭、true=开启】关闭时调试卡死
            autoOpenSettings: 3000,                     // 获取设备码时自动打开设置时间【3000=3秒，iOS17起不支持自动打开、会有弹框引导】
            /**
             * 签名配置
             **/
            changeNameSwitch: true,                     // 当后台开启前端修改功能时、是否打开修改名称【false=关闭、true=开启】
            changeIconSwitch: true,                     // 当后台开启前端修改功能时、是否打开修改图标【false=关闭、true=开启】
            changeAppIDSwitch: true,                    // 当后台开启前端修改功能时、是否打开修改AppID【false=关闭、true=开启】
            changeVersionSwitch: true,                  // 当后台开启前端修改功能时、是否打开修改版本号【false=关闭、true=开启】
            changeMultipleSwitch: true,                 // 当后台开启前端修改功能时、是否打开应用多开签名开关【false=关闭、true=开启】
            changeMinOSSwitch: true,                    // 当后台开启前端修改功能时、是否打开修改移除版本限制【false=关闭、true=开启】
            changeUrlJumpSwitch: true,                  // 当后台开启前端修改功能时、是否打开修改移除应用跳转【false=关闭、true=开启】
            changeFileAccessSwitch: true,               // 当后台开启前端修改功能时、是否打开修改开启文件访问【false=关闭、true=开启】
        }

        /**
         * V2-2.0.0起 废除原来的语言包功能改为以下方式进行全局 Hook 替换
         *
         * 为了方便用户快速自定义所有页面内容
         * 删除了原有的多语言包方法，原因：多语言包没次都要执行一次请求，占用资源、影响用户体验
         *
         * 所以本处改为全局替换方法、网站管理员可以通过此方法修改此 UI 页面所有文字、包括服务器回调的信息
         * 使用方法如下：
         *
         * 修改单个：const langPack = { '在线签名': '签名页面', }
         * 其中的 “签名下载” 为原有显示文本，“在线签名” 为要替换的文字
         *
         * 修改多个：const langPack = { '在线签名': '签名页面', '证书检测': '在线检测', '查询签名': '在线查询', '帮助中心': '在线帮助', }
         *
         * 如果您不需要修改、也可以将：const langPack = {} 删除或注释
         **/
        window.langPack = {
            // '在线签名': '签名页面', // 这里使用注释、将不执行修改
        }
    </script>
    <script type="text/javascript" src="{{ config('api.basics.cdn') }}/theme/weui/js/zepto.min.js"></script>
    <script type="text/javascript" src="{{ config('api.basics.cdn') }}/theme/weui/js/weui.min.js"></script>
    <script type="text/javascript" src="{{ config('api.basics.cdn') }}/theme/weui/js/file-saver.js"></script>
    <script type="text/javascript" src="{{ config('api.basics.cdn') }}/theme/weui/js/jszip.js"></script>
